inline constexpr std::optional<std::span<const EmbeddedConwayTerm>>
LookupEmbeddedConwayPoly(uint32_t characteristic, uint32_t degree) noexcept {
  auto it = std::lower_bound(
      kEmbeddedConwayEntries.begin(), kEmbeddedConwayEntries.end(),
      std::pair<uint32_t, uint32_t>{characteristic, degree},
      [](const EmbeddedConwayEntry& entry,
         const std::pair<uint32_t, uint32_t>& target) {
        if (entry.characteristic != target.first) {
          return entry.characteristic < target.first;
        }
        return entry.degree < target.second;
      });

  if (it != kEmbeddedConwayEntries.end() &&
      it->characteristic == characteristic && it->degree == degree) {
    return std::span<const EmbeddedConwayTerm>(
        kEmbeddedConwayTerms.data() + it->offset, it->count);
  }
  return std::nullopt;
}

